'use strict';
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={spark:'<path d="m12 3 2.3 6.7L21 12l-6.7 2.3L12 21l-2.3-6.7L3 12l6.7-2.3Z"/><path d="m20 2 .6 1.4L22 4l-1.4.6L20 6l-.6-1.4L18 4l1.4-.6Z"/>',studio:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="m10 9 5 3-5 3Z"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',book:'<path d="M3 4h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v15h-6a4 4 0 0 0-3 2 4 4 0 0 0-3-2H3Z"/><path d="M12 6v15"/>',image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.5"/><path d="m3 16 5-5 5 6 3-3 5 5"/>',history:'<path d="M3 12a9 9 0 1 0 3-6.7L3 8"/><path d="M3 3v5h5M12 7v5l3 2"/>',settings:'<path d="m9 3-1 3-3 1 1 3-3 2 2 3 3-1 1 3 3 1 2-3 3 1 2-3-2-2 1-3-3-1-1-3Z"/><circle cx="11" cy="10" r="3"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',leaf:'<path d="M20 3c0 12-5 19-12 17C0 18 3 6 20 3Z"/><path d="M5 20 15 9"/>',file:'<path d="M14 3H5v18h14V8Z"/><path d="M14 3v5h5M8 12h8m-8 4h5"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',edit:'<path d="m14 5 5 5M4 20l5-1L21 7l-5-5L4 14Z"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',play:'<path d="m8 4 13 8-13 8Z"/>',video:'<rect x="3" y="5" width="12" height="14" rx="2"/><path d="m15 10 6-4v12l-6-4Z"/>',audio:'<path d="M9 18V5l11-2v13M9 8l11-2"/><ellipse cx="6" cy="18" rx="3" ry="2"/><ellipse cx="17" cy="16" rx="3" ry="2"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',refresh:'<path d="M20 7V2l-3 3a8 8 0 1 0 3 11M20 7h-5"/>',flower:'<path d="M12 12C1-1 22-1 12 12c13-10 13 11 0 0 11 13-10 13 0 0-13 11-13-10 0 0Z"/><circle cx="12" cy="12" r="2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.5"/>',folder:'<path d="M3 7V4h7l2 3h9v13H3Z"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.spark}</svg>`;
const names={studio:'Студия',profiles:'Профили моделей',knowledge:'Библиотека знаний',references:'Референсы',history:'История',story:'Сценарий',settings:'Подключения'};
let S,view='studio',tab='idea',busy=false,query='',category='',saveTimer,saveQueue=Promise.resolve(),savedWorkspace='',queuedWorkspace='',toastTimer,editorRef,editorProfile,editorDoc,uploadedMedia=null,prepared=null,docReview=false;
const profile=()=>S.profiles.find(p=>p.id===S.workspace.profile_id)||S.profiles[0];
const plural=(n,one,few,many)=>n+' '+(n%100>=11&&n%100<=14?many:n%10===1?one:n%10>=2&&n%10<=4?few:many);
const date=s=>s?new Date(s).toLocaleDateString('ru-RU',{day:'numeric',month:'short',year:'numeric'}):'Не проверено';
const linkedDocs=()=>S.documents.filter(d=>d.enabled&&(!d.profiles.length||d.profiles.includes(profile().id))&&(!d.providers||d.providers.includes('*')||d.providers.includes(profile().provider)));
const chosen=()=>S.references.filter(r=>S.workspace.reference_ids.includes(r.id)).map(r=>({...r,role:S.workspace.reference_roles?.[r.id]||r.role}));
const btn=(text,action,ic='',classes='',extra='')=>`<button type="button" class="btn ${classes}" data-action="${action}" ${extra}>${ic?icon(ic):''}${text}</button>`;
const option=(value,label,selected)=>`<option value="${esc(value)}" ${selected?'selected':''}>${esc(label)}</option>`;
const badge=(text,cl='')=>`<span class="mini-tag ${cl}">${esc(text)}</span>`;
const field=(label,input)=>`<label class="form-field"><span>${label}</span>${input}</label>`;
const switchInput=(name,checked,extra='')=>`<label class="switch"><input type="checkbox" name="${name}" ${checked?'checked':''} ${extra}><i></i></label>`;
const input=(name,value='',placeholder='',type='text',extra='')=>`<input name="${name}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${extra}>`;
const textarea=(name,value='',placeholder='',extra='')=>`<textarea name="${name}" placeholder="${esc(placeholder)}" ${extra}>${esc(value)}</textarea>`;
let onlineCsrf;
async function api(path,body){
 if(!onlineCsrf){const me=await fetch('/auth/me',{credentials:'same-origin'});if(me.status===401){window.location.assign('/login');throw Error('Войдите в студию');}const identity=await me.json();onlineCsrf=identity.csrf;}
 const r=await fetch('/api/'+path,body===undefined?{credentials:'same-origin'}:{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Studio-Request':'local','X-CSRF-Token':onlineCsrf},body:JSON.stringify(body)});
 const d=await r.json();if(r.status===401){window.location.assign('/login');throw Error(d.error||'Сессия истекла');}if(!r.ok)throw Error(d.error||'Ошибка запроса');return d;
}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6000);}
function defaults(p){return Object.fromEntries(Object.entries(p.schema).map(([k,v])=>[k,v.default]));}
function params(){return {...defaults(profile()),...S.workspace.parameters};}
function autosave(){clearTimeout(saveTimer);$('.save-state').innerHTML=icon('refresh')+'Сохраняем…';saveTimer=setTimeout(saveWorkspace,500);}
function saveWorkspace(){
 clearTimeout(saveTimer);const snapshot=structuredClone(S.workspace),signature=JSON.stringify(snapshot);
 if(signature===queuedWorkspace)return saveQueue;
 queuedWorkspace=signature;
 saveQueue=saveQueue.catch(()=>{}).then(async()=>{if(signature!==savedWorkspace){await api('workspace',snapshot);savedWorkspace=signature;}if($('.save-state'))$('.save-state').innerHTML=icon('check')+(JSON.stringify(S.workspace)===savedWorkspace?'Сохранено в студии':'Сохраняем…');}).catch(e=>{if(queuedWorkspace===signature)queuedWorkspace='';toast(e.message);throw e;});return saveQueue;
}
async function reload(){const w=S.workspace;S=await api('state');S.workspace=w;}
function openModal(title,body,footer=''){const d=$('#modal');d.innerHTML=`<div class="modal-header"><h2>${title}</h2><button type="button" class="icon-btn" data-action="close" aria-label="Закрыть">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!d.open)d.showModal();}
function closeModal(){$('#modal').close();uploadedMedia=null;}
function download(name,value,mime='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type:mime}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function renderStory(){return '<div class="panel empty">Открываем сценарную мастерскую…</div>';}
function render(){const p=profile();S.workspace.profile_id=p.id;const nav=[['studio','studio'],['story','file'],['profiles','grid'],['knowledge','book'],['references','image'],['history','history']];$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">${icon('flower')}</div><div class="brand-title">AI Video<br><em>Studio</em></div></div><div class="sidebar-label">ВАШЕ ТВОРЧЕСКОЕ ПРОСТРАНСТВО</div><nav class="nav" aria-label="Основная навигация">${nav.map(([v,i])=>`<button class="${view===v?'active':''}" data-view="${v}">${icon(i)}${names[v]}${v==='knowledge'?`<span class="nav-count">${S.documents.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-footer"><div class="sidebar-note">${icon('leaf')}<strong>Место для ваших идей</strong>Вы придумываете историю.<br>Студия помогает ей ожить.</div><nav class="nav"><button class="${view==='settings'?'active':''}" data-view="settings">${icon('settings')}Подключения</button></nav><div class="local-indicator"><span class="dot"></span>Общая студия · online</div></div></aside><div class="main-wrap"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Открыть меню">${icon('menu')}</button><span>Рабочее пространство</span><span>/</span><strong>${names[view]}</strong></div><div class="top-actions"><span class="save-state">${icon('check')}Сохранено в студии</span><div class="online-tools"><button class="btn ghost" data-online-action="refresh">Обновить</button><button class="btn ghost" data-online-action="logout">Выйти</button></div><div class="avatar" aria-label="Ваш аккаунт" title="${esc(S.user?.email||'')}">${esc((S.user?.name||'a').slice(0,1))}.</div></div></header><main class="main"><p class="shared-caption"><strong>Общее пространство</strong> · библиотека, референсы и история доступны вам обеим. API-ключи и текущий черновик — личные.</p>${({studio:renderStudio,profiles:renderProfiles,knowledge:renderKnowledge,references:renderReferences,history:renderHistory,story:renderStory,settings:renderSettings}[view])()}<footer class="footnote"><span>AI VIDEO STUDIO &nbsp; / &nbsp; СОЗДАНО ДЛЯ ВАШИХ ИСТОРИЙ</span><div class="palette" aria-label="Оливковый, розовый и кремовый"><i></i><i></i><i></i><i></i></div><span>MAKE SOMETHING MOVE.</span></footer></main></div></div>`;}
function heading(title,subtitle,action='',overline='AI DIRECTOR ENGINE'){return `<div class="page-heading"><div><div class="page-overline">${overline}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function renderStudio(){const p=profile(),docs=linkedDocs(),r=S.workspace.result;return `${heading('Ваша следующая история','От первой идеи до кадра, который хочется пересмотреть.',btn('Новый замысел','new-idea','plus','ghost'))}<section class="hero"><div><div class="eyebrow">A LITTLE IMAGINATION. A LITTLE MAGIC.</div><h2>Придумайте.<br><em>Оживите.</em></h2><p>Идея, референсы и точные слова —<br>всё для вашей следующей маленькой истории.</p></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><div class="hero-play">${icon('play')}</div><span class="star a">✧</span><span class="star b">✳</span><span class="hero-tag">FROM IDEA TO MOTION</span></div></section>${busy?`<div class="busy-banner"><span class="spinner"></span>AI-режиссёр готовит промпт с учётом модели и ваших референсов…</div>`:''}<div class="studio-grid"><div><section class="panel"><div class="tabstrip"><button data-action="tab-idea" class="${tab==='idea'?'active':''}">01 &nbsp; Ваш замысел</button><button data-action="tab-result" class="${tab==='result'?'active':''}">02 &nbsp; Готовый промпт ${r?'·':''}</button></div><div class="panel-body">${tab==='idea'?`<div class="brief-header"><span>Какую историю расскажем?</span><small>Можно просто своими словами</small></div><textarea name="brief" class="brief" placeholder="Девушка идёт по цветущему саду. Ветер чуть колышет платье, камера плавно следует за ней. Тёплый вечерний свет, ощущение лёгкости…">${esc(S.workspace.brief)}</textarea><div class="inspiration"><button class="chip" data-example="cinema">Кинематографично</button><button class="chip" data-example="product">Предметная съёмка</button><button class="chip" data-example="dream">Немного волшебства</button></div><div class="section-label"><span>Визуальные референсы <span style="color:var(--muted)">(${chosen().length})</span></span><button class="text-button" data-action="pick-refs">${icon('plus')}Добавить</button></div><div class="ref-grid">${chosen().slice(0,6).map(r=>refTile(r)).join('')||[['image','Герой и первый кадр','Изображение'],['image','Мир вашей истории','Референс атмосферы'],['video','Движение и ритм','Видеореференс']].map(([ic,title,sub])=>`<button class="ref-empty" data-action="add-ref" data-type="${ic}">${icon(ic)}<span>${title}</span><small>${sub}</small></button>`).join('')}</div>${chosen().length>6?`<p class="help">И ещё ${chosen().length-6} референсов — все будут учтены.</p>`:''}${r?`<div class="restore-note">${icon('spark')} Промпт уже готов. Дополните замысел и нажмите «Улучшить промпт» или откройте вторую вкладку.</div>`:''}`:renderResult()}</div><div class="composer-footer"><p>${icon('lock')}Видеогенерация — только после подтверждения</p>${tab==='idea'?`<button class="btn primary" data-action="direct" ${busy?'disabled':''}>${busy?'<span class="spinner"></span>':icon('spark')}${r?'Улучшить промпт':'Создать промпт'}${icon('arrow')}</button>`:`${btn('К замыслу','tab-idea','','ghost small')}${btn('Проверить и создать видео','prepare','play','primary',r?'':'disabled')}`}</div></section><div class="section-intro">${icon('info')} ${S.settings.prompt.url?'Подключён Prompt AI · '+esc(S.settings.prompt.model||'выберите модель'):'Начните с замысла. Для AI-режиссёра подключите свою текстовую или мультимодальную модель.'} <button class="text-button" data-view="settings">Настроить ${icon('arrow')}</button></div></div><aside class="inspector"><section class="panel"><div class="panel-head"><h2 class="panel-title">${icon('settings')}Параметры генерации</h2>${badge('Модель')}</div><div class="panel-body"><label class="form-field" style="margin-top:0"><span>Видеомодель и режим</span><select name="active-profile">${S.profiles.map(x=>option(x.id,x.name+' · '+x.mode,p.id===x.id)).join('')}</select></label><div class="model-card"><div class="model-symbol">${icon('spark')}</div><div><strong>${esc(p.name)}</strong><small>${esc(p.mode)} · ${esc(providerName(p.provider))}</small></div><button class="icon-btn" data-action="profile-info" aria-label="Информация о профиле">${icon('info')}</button></div><div class="two-col">${Object.entries(p.schema).filter(([,rule])=>rule.type!=='boolean').map(([k,rule])=>field(parameterLabel(k),rule.enum?`<select data-param="${esc(k)}">${rule.enum.map(v=>option(v,v===-1?'Авто':k==='duration'?v+' сек':v,params()[k]===v)).join('')}</select>`:input('param-'+k,params()[k],'',rule.type==='string'?'text':'number',`data-param="${esc(k)}"`))).join('')}</div>${Object.entries(p.schema).filter(([,v])=>v.type==='boolean').map(([k])=>`<div class="toggle-row"><div>${parameterLabel(k)}<small>Если поддерживается выбранной моделью</small></div>${switchInput('param-'+k,params()[k],`data-param="${esc(k)}"`)}</div>`).join('')}<p class="inspector-hint">${p.contract==='t2v'?'Новая сцена из текста: референсы не требуются.':p.contract==='i2v'?'Кадр задаёт композицию. Промпт — движение, свет и настроение.':p.contract==='r2v'?'Каждый референс сохраняет свою роль в новой сцене.':'Движение и длительность задаёт исходное видео.'}</p></div></section><section class="panel"><div class="panel-head"><h2 class="panel-title">${icon('book')}Знания для модели</h2>${badge(docs.length+' док.')}</div><div class="panel-body"><div class="context-note">${icon('leaf')}<span>В контекст попадут только активные и подходящие разделы.</span></div>${docs.slice(0,4).map(d=>`<button class="doc-mini" data-action="read-doc" data-id="${esc(d.id)}" style="width:100%;text-align:left">${icon('file')}<span>${esc(d.title)}</span><small>v${d.version}</small></button>`).join('')}<button class="text-button" data-action="show-context" style="margin-top:13px">Посмотреть контекст ${icon('arrow')}</button></div></section></aside></div>`;}
function providerName(id){return S.settings.video[id]?.name||id;}
function parameterLabel(k){return ({duration:'Длительность',resolution:'Разрешение',ratio:'Формат кадра',generate_audio:'Звук в видео',aspect_ratio:'Формат кадра',bitrate_mode:'Битрейт',watermark:'Водяной знак'})[k]||esc(k);}
const mediaUrl=(r,preview=false)=>r.file?'/media/'+encodeURIComponent(r.file)+(preview?'?preview=1':''):r.remote_url;
function refTile(r){return `<button class="ref-tile" data-action="edit-ref" data-id="${esc(r.id)}" title="${esc(r.name)}">${r.type==='image'?`<img loading="lazy" decoding="async" src="${esc(mediaUrl(r,true))}" alt="${esc(r.name)}">`:r.type==='video'&&r.frames?.length?`<img loading="lazy" decoding="async" src="/media/${esc(r.frames[0])}?preview=1" alt="Ключевой кадр ${esc(r.name)}">`:icon(r.type)}<span class="tile-check">${icon('check')}</span><span class="ref-caption"><strong>${esc(r.id)}</strong><span>${esc(r.role)}</span></span></button>`;}
function renderResult(){const r=S.workspace.result;if(!r)return `<div class="empty">${icon('spark')}<strong>Здесь начнётся движение</strong>Опишите замысел на первой вкладке.<br>AI-режиссёр соберёт промпт для вашей модели.${btn('Вернуться к замыслу','tab-idea','arrow','small')}</div>`;return `<div class="result-content"><div class="brief-header"><span>Ваш промпт <small>· можно редактировать</small></span><button class="text-button" data-action="copy-prompt">${icon('copy')}Копировать</button></div>${textarea('result-prompt',r.prompt,'')}<p class="result-detail">${esc(r.explanation||'Локальный черновик. Готовый текст можно изменить перед отправкой.')}</p>${(r.warnings||[]).map(w=>`<div class="warning">${esc(w)}</div>`).join('')}<div class="result-docs">${(r.context||[]).filter((x,i,a)=>a.findIndex(y=>y.document_id===x.document_id)===i).map(d=>`<button class="chip" data-action="read-doc" data-id="${esc(d.document_id)}">${esc(d.title)} · v${d.version}</button>`).join('')}</div><div class="inline-actions" style="margin-top:17px">${btn('Сохранить черновик','save-draft','file','small')}${btn('Экспорт промпта','export-prompt','download','small ghost')}</div></div>`;}
function renderProfiles(){return `${heading('Профили моделей','У каждой модели — свой язык, возможности и точные ограничения.',`<div class="inline-actions">${btn('Импорт','import-profile','upload','ghost')}${btn('Новый профиль','add-profile','plus','primary')}</div>`)}<div class="toolbar"><input name="search" placeholder="Найти модель или режим…" value="${esc(query)}"></div><div class="card-grid">${S.profiles.filter(p=>(p.name+' '+p.mode).toLowerCase().includes(query.toLowerCase())).map(p=>`<article class="profile-card"><div class="card-top"><div class="card-icon ${p.provider==='nano'?'pink':''}">${icon(p.contract==='swap'?'image':'spark')}</div>${badge(p.status==='verified'?'Проверено '+(p.verified_at||''):'Требует проверки',p.status==='verified'?'':'warn')}</div><h2>${esc(p.name)}</h2><div class="mode">${esc(p.mode)}</div><p>${esc(p.system)}</p><div class="card-meta"><span>${esc(providerName(p.provider))}</span><span>${S.documents.filter(d=>d.profiles.includes(p.id)).length} документов</span><span>Версия ${p.version}</span></div><div class="card-actions">${btn('Открыть в студии','use-profile','arrow','primary small',`data-id="${esc(p.id)}"`)}${btn('Настроить','edit-profile','edit','small',`data-id="${esc(p.id)}"`)}<button class="icon-btn" data-action="copy-profile" data-id="${esc(p.id)}" title="Копировать">${icon('copy')}</button><button class="icon-btn" data-action="export-profile" data-id="${esc(p.id)}" title="Экспорт">${icon('download')}</button>${!['seedance-i2v','seedance-r2v','genjutsu-motion','genjutsu-swap','hf-seedance-i2v','hf-seedance-r2v','hf-genjutsu-motion','hf-genjutsu-swap','seedance-t2v','hf-seedance-t2v'].includes(p.id)?`<button class="icon-btn danger" data-action="delete-profile" data-id="${esc(p.id)}" title="Удалить">${icon('trash')}</button>`:''}</div></article>`).join('')||'<div class="empty">Профили не найдены.</div>'}</div>`;}
function renderKnowledge(){const docs=S.documents.filter(d=>(!category||d.category===category)&&(d.title+' '+d.content).toLowerCase().includes(query.toLowerCase()));return `${heading('Библиотека знаний','Документация и ваши заметки. Нужные знания — в нужный момент.',`<div class="inline-actions">${btn('Загрузить .md / .txt','import-doc','upload','ghost')}${btn('Новый документ','add-doc','plus','primary')}</div>`)}<div class="toolbar"><input name="search" placeholder="Поиск по названиям и содержимому…" value="${esc(query)}"><select name="category-filter">${option('','Все категории',!category)}${S.categories.map(c=>option(c,c,category===c)).join('')}</select><span class="help" style="margin:0">${plural(docs.length,'документ','документа','документов')}</span></div><div class="card-grid">${docs.map(d=>`<article class="doc-card"><div class="card-top"><div class="card-icon ${d.category==='User Instructions'?'pink':''}">${icon('file')}</div><div class="toggle-row" style="margin:0"><span>${d.enabled?'В контексте':'Отключён'}</span>${switchInput('doc-enable',d.enabled,`data-doc-enable="${esc(d.id)}"`)}</div></div><div class="category">${esc(d.category)}</div><h2 style="margin-top:8px">${esc(d.title)}</h2><p>${esc(d.content.replace(/#+/g,'').slice(0,180))}</p><div class="card-meta"><span>${plural(d.profiles.length,'профиль','профиля','профилей')}</span><span>v${d.version}</span><span>${date(d.updated_at)}</span></div><div class="card-actions">${btn('Читать и редактировать','edit-doc','edit','small',`data-id="${esc(d.id)}"`)}${btn('Экспорт','export-doc','download','small ghost',`data-id="${esc(d.id)}"`)}<button class="icon-btn danger" data-action="delete-doc" data-id="${esc(d.id)}" title="Удалить">${icon('trash')}</button></div></article>`).join('')||'<div class="empty">Здесь пока нет документов. Создайте заметку или загрузите .md / .txt.</div>'}</div>`;}
function renderReferences(){return `${heading('То, что вдохновляет','Герои, атмосфера, движение. У каждого референса своя роль.',btn('Добавить референс','add-ref','plus','primary'))}<div class="toolbar"><input name="search" placeholder="Имя, роль или описание…" value="${esc(query)}"><span class="help" style="margin:0">${S.references.length} файлов · общее хранилище</span></div>${S.references.length?`<div class="media-grid">${S.references.filter(r=>(r.name+' '+r.role+' '+r.description).toLowerCase().includes(query.toLowerCase())).map(r=>`<article class="media-card"><button type="button" class="media-preview" data-action="preview-ref" data-id="${esc(r.id)}" aria-label="Открыть ${esc(r.name)} целиком">${r.type==='image'?`<img loading="lazy" decoding="async" src="${esc(mediaUrl(r,true))}" alt="${esc(r.name)}">`:r.type==='video'&&r.frames?.length?`<img loading="lazy" decoding="async" src="/media/${esc(r.frames[0])}?preview=1" alt="Ключевой кадр ${esc(r.name)}"><span class="media-play">${icon('play')}</span>`:icon(r.type)}</button><div class="media-info"><div class="reference-title"><h3>${esc(r.name)}</h3>${badge(r.id)}</div><p>${esc(r.role)}${r.duration?' · '+r.duration.toFixed(1)+' сек':''}</p><p class="help">${esc(r.description||'Добавьте описание, чтобы режиссёр точнее понял роль файла.')}</p><div class="card-actions">${btn('Открыть','preview-ref','image','small',`data-id="${esc(r.id)}"`)}${btn('Описание и роль','edit-ref','edit','small',`data-id="${esc(r.id)}"`)}<button class="icon-btn danger" data-action="delete-ref" data-id="${esc(r.id)}" title="Удалить">${icon('trash')}</button></div></div></article>`).join('')}</div>`:`<div class="panel"><div class="empty" style="padding:65px 20px">${icon('image')}<strong>Вдохновение для вашей истории</strong>Загрузите изображения, видео или аудио.<br>Метки image1 и video1 появятся после сохранения.${btn('Добавить первый референс','add-ref','plus','primary')}</div></div>`}`;}
function showMediaPreview(r){
 if(!r)return;const url=esc(mediaUrl(r));
 const content=r.type==='image'?`<img class="reference-full-image" src="${url}" alt="${esc(r.name)}">`:r.type==='video'?`<video class="reference-full-video" controls preload="metadata" src="${url}"></video>`:`<audio controls preload="metadata" src="${url}"></audio>`;
 openModal(esc(r.name),`<div class="reference-full">${content}</div><p class="help">${esc(r.description||r.role)}</p>`,`<a class="btn ghost" href="${url}" target="_blank" rel="noopener">Открыть оригинал</a>`+btn('Закрыть','close','','primary'));
}
function renderHistory(){const items=[...S.history].reverse();return `${heading('Ваш творческий след','Идеи, промпты и видео, к которым всегда можно вернуться.',btn('Экспорт истории','export-history','download','ghost'))}${S.jobs.length?`<h2 class="panel-title" style="margin-bottom:14px">Видеогенерации</h2><div class="list-panel" style="margin-bottom:25px">${[...S.jobs].reverse().map(j=>`<div class="history-row"><div class="card-icon pink">${icon('video')}</div><div><h3>${esc(j.title)}</h3><small>${esc(j.provider)} · ${esc(j.status)} · ${date(j.created_at)}</small>${j.error?`<p class="warning">${esc(j.error)}</p>`:''}${(j.outputs||[]).map(o=>{const u=typeof o==='string'?o:o.url;return u&&/^https:\/\//.test(u)?`<div class="job-output"><video controls preload="metadata" src="${esc(u)}"></video><br><a href="${esc(u)}" target="_blank" rel="noopener noreferrer">Открыть видео у провайдера</a></div>`:'';}).join('')}</div><div class="actions">${j.remote_id?btn('Проверить статус','poll-job','refresh','small',`data-id="${esc(j.id)}"`):''}</div></div>`).join('')}</div>`:''}<h2 class="panel-title" style="margin-bottom:14px">Промпты и черновики</h2>${items.length?`<div class="list-panel">${items.map(h=>`<div class="history-row"><div class="card-icon">${icon(h.kind==='draft'?'file':'spark')}</div><div><h3>${esc(h.title)}</h3><small>${esc(S.profiles.find(p=>p.id===h.profile_id)?.name||'Профиль удалён')} · ${h.kind==='draft'?'Черновик':'AI-промпт'} · ${date(h.created_at)}</small></div><div class="actions">${btn('Продолжить','restore-history','arrow','small',`data-id="${esc(h.id)}"`)}<button class="icon-btn danger" data-action="delete-history" data-id="${esc(h.id)}" aria-label="Удалить запись">${icon('trash')}</button></div></div>`).join('')}</div>`:`<div class="panel"><div class="empty">${icon('history')}<strong>Каждая история с чего-то начинается</strong>Созданные промпты и сохранённые черновики появятся здесь.${btn('Вернуться в студию','go-studio','arrow','small')}</div></div>`}`;}

function showProfileEditor(p=null){editorProfile=p?structuredClone(p):{id:'',name:'',mode:'Text to Video',provider:'custom',endpoint:'',model:'',system:'',user_instructions:'',roles:['Main Character','Environment'],schema:{duration:{type:'integer',minimum:1,maximum:10,default:5}},request_template:{model:'$model',prompt:'$prompt',$merge:'$parameters',reference_images:'$images'},poll_url:'',source:'',status:'unverified',version:1,verified_at:''};const x=editorProfile,locked=['seedance-i2v','seedance-r2v','genjutsu-motion','genjutsu-swap','hf-seedance-i2v','hf-seedance-r2v','hf-genjutsu-motion','hf-genjutsu-swap','seedance-t2v','hf-seedance-t2v'].includes(x.id);openModal(p?'Профиль модели':'Новая модель',`<form id="profile-form">${field('Название',input('name',x.name,'Название модели','text','required'))}<div class="form-row">${field('Режим генерации',input('mode',x.mode,'Text to Video','text','required'))}${field('ID провайдера (латиницей)',input('provider',x.provider,'custom','text',locked?'disabled':'required pattern="[a-zA-Z0-9_-]+"'))}</div>${field('Точный endpoint генерации',input('endpoint',x.endpoint,'https://api.provider.com/v1/tasks','url',locked?'disabled':'required'))}${field('Model ID в API',input('model',x.model,'provider/model-id','text',locked?'disabled':'required'))}${field('Системные инструкции профиля',textarea('system',x.system,'Поведение режиссёра для этой модели','required'))}${field('Ваши дополнительные инструкции',textarea('user_instructions',x.user_instructions,'Предпочтения по стилю, композиции, языку…'))}${field('Роли референсов (через запятую)',input('roles',x.roles.join(', '),'Main Character, Environment','text',locked?'disabled':''))}${field('Техническая схема параметров · JSON',textarea('schema',JSON.stringify(x.schema,null,2),'',`class="code" ${locked?'disabled':''}`))}${field('Шаблон тела API-запроса · JSON',textarea('request_template',JSON.stringify(x.request_template,null,2),'',`class="code" ${locked?'disabled':''}`))}<p class="help">Переменные: $model, $prompt, $parameters, $images, $videos, $audios, $role.First Frame. $merge добавляет объект параметров. Код и команды не выполняются.</p>${field('URL проверки задания · {id} заменяется на ID задачи',input('poll_url',x.poll_url,'https://api.provider.com/v1/tasks/{id}','text',locked?'disabled':''))}${field('Источник технических ограничений',input('source',x.source||'','https://docs.provider.com','text'))}<div class="form-row">${field('Версия',input('version',x.version,'','number','min="1"'))}${field('Дата проверки',input('verified_at',x.verified_at,'','date'))}</div><label class="check-group" style="margin-top:20px"><input name="verified" type="checkbox" ${x.status==='verified'?'checked':''}>Схема сверена с документацией выбранного endpoint</label>${locked?'<div class="help-box">Технические поля встроенного профиля закреплены за проверенным API. Для другого endpoint создайте копию.</div>':''}</form>`,btn('Отмена','close','','ghost')+'<button type="submit" form="profile-form" class="btn primary">'+icon('check')+'Сохранить профиль</button>');}
function showDocEditor(d=null,content=null,title=null){editorDoc=d?structuredClone(d):{id:'',title:title||'',category:'User Instructions',source:'Локальный документ',profiles:[profile().id],enabled:true,content:content||'',version:1};docReview=false;const x=editorDoc;openModal(d?'Документ библиотеки':'Новый документ',`<form id="doc-form">${field('Название',input('title',x.title,'Название документа','text','required'))}<div class="form-row">${field('Категория',`<select name="category">${S.categories.map(c=>option(c,c,c===x.category)).join('')}</select>`)}${field('Источник',input('source',x.source,'URL или название источника'))}</div>${field('Содержание · Markdown или текст',textarea('content',x.content,'# Раздел\nПолезные знания для AI-режиссёра…','class="code" style="min-height:240px" required'))}<label class="file-drop">${icon('upload')}Заменить текст из .md / .txt<input name="doc-file" type="file" accept=".md,.txt,text/plain,text/markdown"></label>${d&&/^https:\/\//.test(x.source)?btn('Проверить источник','check-doc-source','refresh','small ghost',`data-id="${esc(d.id)}"`):''}<span class="field-label" style="margin-top:20px">Использовать с профилями</span>${S.profiles.map(p=>`<label class="check-group"><input name="linked-profile" type="checkbox" value="${esc(p.id)}" ${x.profiles.includes(p.id)?'checked':''}>${esc(p.name)} · ${esc(p.mode)}</label>`).join('')}<label class="check-group" style="margin-top:16px"><input name="enabled" type="checkbox" ${x.enabled?'checked':''}>Документ активен и может попадать в контекст</label><div id="doc-diff"></div>${d?`<p class="help">Добавлен: ${date(d.created_at)} · Обновлён: ${date(d.updated_at)} · Версия ${d.version}. Изменения документа не меняют техническую схему модели.</p>`:''}</form>`,btn('Отмена','close','','ghost')+'<button type="submit" form="doc-form" class="btn primary" id="doc-submit">'+icon('check')+'Сохранить документ</button>');}
function showRefEditor(r=null,type='image'){editorRef=r?structuredClone(r):{id:'',name:'',type:type||'image',role:profile().roles[0]||'Main Character',description:'',remote_url:'',duration:0,width:0,height:0,size:0,fps:0,metadata_checked:false};uploadedMedia=null;const x=editorRef,roles=[...new Set([...profile().roles,'First Frame','Last Frame','Main Character','Environment','Outfit Reference','Style Reference','Motion Reference','Replacement Object','Audio Reference'])];if(!r)x.role=x.type==='video'?'Motion Reference':x.type==='audio'?'Audio Reference':x.role;openModal(r?'Настроить референс':'Новый референс',`<form id="ref-form"><label class="file-drop">${icon('upload')}<span>${r?'Выбрать другой файл':'Изображение, видео или аудио'}</span><input type="file" name="media-file" accept="image/png,image/jpeg,image/webp,image/gif,image/bmp,video/mp4,video/webm,video/quicktime,audio/mpeg,audio/wav,audio/ogg"><span class="upload-progress" id="upload-status" role="status">${r?.file?'Файл сохранён в общей студии':''}</span></label>${field('Название',input('name',x.name,'Например, героиня в саду','text','required'))}<div class="form-row">${field('Тип медиа',`<select name="type">${['image','video','audio'].map(t=>option(t,{image:'Изображение',video:'Видео',audio:'Аудио'}[t],x.type===t)).join('')}</select>`)}${field('Роль',`<select name="role">${roles.map(role=>option(role,role,x.role===role)).join('')}</select>`)}</div>${field('Визуальное описание',textarea('description',x.description,'Кто или что здесь изображено? Что важно сохранить?'))}${field('Публичный HTTPS URL для видео-API (если требуется)',input('remote_url',x.remote_url,'https://…','url'))}<p class="help">Изображения Atlas Cloud можно отправлять прямо с компьютера. Для видео/аудио и всех референсов NanoAPI нужен публичный URL. Студия не публикует ваши файлы автоматически.</p><div class="form-row">${field('Ширина, px',input('width',x.width||'','','number','min="0"'))}${field('Высота, px',input('height',x.height||'','','number','min="0"'))}</div><div class="form-row">${field('Длительность, сек (для видео/аудио)',input('duration',x.duration||'','','number','min="0" step="0.001"'))}${field('FPS видео',input('fps',x.fps||'','','number','min="0" step="0.01"'))}</div>${field('Размер удалённого файла, MB',input('size_mb',x.size?Math.round(x.size/1024/1024*100)/100:'','','number','min="0" step="0.01"'))}<label class="check-group"><input name="metadata_checked" type="checkbox" ${x.metadata_checked?'checked':''}>Проверены параметры удалённого видео: MP4/MOV, H.264/H.265, 24–60 FPS</label><p class="help">Метаданные локальных файлов считываются автоматически, видео получает три ключевых кадра. Для удалённых медиа заполните параметры после проверки файла.</p><label class="check-group"><input name="select-now" type="checkbox" checked>Использовать в текущем замысле</label></form>`,btn('Отмена','close','','ghost')+'<button type="submit" form="ref-form" class="btn primary" id="ref-submit">'+icon('check')+'Сохранить референс</button>');}
function showRefPicker(){openModal('Референсы для истории',`<p class="section-intro">Выберите медиа для ${esc(profile().name)} · ${esc(profile().mode)}. Роль сохраняется в самом референсе.</p>${S.references.length?S.references.map(r=>`<label class="check-group"><input name="pick-reference" type="checkbox" value="${esc(r.id)}" ${S.workspace.reference_ids.includes(r.id)?'checked':''} ${profile().roles.includes(r.role)?'':'disabled'}><span><strong>${esc(r.id)}</strong> · ${esc(r.name)}<br><small>${esc(r.role)}${profile().roles.includes(r.role)?'':' · роль не поддерживается: измените её в библиотеке референсов'}</small></span></label>`).join(''):'<div class="empty">Сначала добавьте изображения, видео или аудио.</div>'}`,btn('Новый референс','add-ref','plus','ghost')+btn('Применить','apply-refs','check','primary'));}
async function changeProfile(id){if(busy){toast('Дождитесь ответа AI-режиссёра');return;}S.workspace.previous_result=S.workspace.result||S.workspace.previous_result;S.workspace.profile_id=id;S.workspace.parameters=defaults(profile());S.workspace.result=null;const count=S.workspace.reference_ids.length;S.workspace.reference_ids=chosen().filter(r=>profile().roles.includes(r.role)).map(r=>r.id);tab='idea';await saveWorkspace();render();if(S.workspace.reference_ids.length<count)toast('Референсы с несовместимыми ролями остались в библиотеке. Контекст переключён на новую модель.');}
async function direct(){if(busy)return;if(!S.workspace.brief.trim()){toast('Сначала опишите ваш замысел');return;}if(!S.settings.prompt.url||!S.settings.prompt.model){openModal('Подключите AI-режиссёра','<p class="section-intro">Укажите Base URL, API-ключ и модель в разделе «Подключения». До подключения можно сохранить замысел и референсы как локальный черновик.</p>',btn('Сохранить черновик','save-draft','file','ghost')+btn('Открыть подключения','go-settings','settings','primary'));return;}await saveWorkspace();busy=true;render();try{const h=await api('director',{profile_id:profile().id,brief:S.workspace.brief,parameters:params(),reference_ids:S.workspace.reference_ids,previous_result:S.workspace.result||S.workspace.previous_result,messages:S.workspace.messages||[]});S.workspace.result=h.result;S.workspace.parameters=h.result.parameters;S.workspace.messages=[...(S.workspace.messages||[]),{role:'user',content:S.workspace.brief},{role:'assistant',content:h.result.prompt}].slice(-12);S.history.push(h);tab='result';await saveWorkspace();toast('Промпт готов. Его можно отредактировать перед генерацией.');}catch(e){toast(e.message);}finally{busy=false;render();}}
async function saveDraft(){const result=S.workspace.result||{prompt:S.workspace.brief,parameters:params(),explanation:'Локальный черновик замысла. AI пока не использовался.',warnings:[],context:[],document_ids:[],profile_id:profile().id};if(!result.prompt.trim()&&!['motion','swap'].includes(profile().contract)){toast('Сначала добавьте замысел или промпт');return;}const h=await api('history',{title:S.workspace.brief.slice(0,90)||result.prompt.slice(0,90),brief:S.workspace.brief,profile_id:profile().id,result,reference_ids:S.workspace.reference_ids});S.history.push(h);await saveWorkspace();closeModal();toast('Черновик сохранён в истории');}
async function prepareVideo(){const r=S.workspace.result;if(!r)return;await saveWorkspace();prepared=await api('prepare',{profile_id:profile().id,prompt:r.prompt,parameters:params(),reference_ids:S.workspace.reference_ids});const t=prepared;openModal('Проверим перед генерацией',`<p class="section-intro">Будет отправлен один запрос видеопровайдеру. Он может списать средства по своему тарифу. Стоимость определяется в кабинете провайдера; студия её не вычисляет.</p><p class="help"><strong>${esc(providerName(t.provider))}</strong><br>${esc(t.endpoint)}</p>${(t.warnings||[]).map(w=>'<div class="warning">'+esc(w)+'</div>').join('')}<pre>${esc(JSON.stringify(t.payload,null,2))}</pre><p class="help">Референсы: ${Object.entries(t.mapping).map(([a,b])=>esc(a)+' → '+esc(b)).join(', ')||'Нет'}</p>${!t.has_key?'<div class="warning">Ключ видеопровайдера не настроен. Сохраните его в подключениях.</div>':''}<label class="check-group"><input type="checkbox" id="paid-confirm">Подтверждаю отправку этого запроса и возможное списание средств видеопровайдером.</label>`,btn('Вернуться','close','','ghost')+btn('Подтвердить платную генерацию','generate','play','pink',t.has_key?'':'disabled'));}
async function generateVideo(button){if(!$('#paid-confirm')?.checked){toast('Подтвердите возможное списание средств');return;}button.disabled=true;try{const j=await api('generate',{ticket:prepared.ticket,confirmed:true});S.jobs.push(j);closeModal();view='history';render();toast('Запрос отправлен. Статус можно проверить в истории.');}catch(e){toast(e.message);await reload();closeModal();view='history';render();}}
async function showContext(){const ctx=await api('context',{profile_id:profile().id,query:S.workspace.brief});openModal('Контекст AI-режиссёра',`<p class="help">${esc(profile().name)} · ${esc(profile().mode)}. До 6 релевантных разделов. Импортированные тексты используются как справочные данные.</p>${ctx.map(d=>`<section class="context-block"><h3>${esc(d.title)}</h3><small>${esc(d.heading)} · ${esc(d.document_id)} · v${d.version}</small><div class="context-content">${esc(d.content)}</div></section>`).join('')||'<div class="empty">Нет активных документов для этого профиля.</div>'}`,btn('Понятно','close','check','primary'));}
async function remove(kind,id){const titles={documents:'документ',profiles:'профиль',references:'референс',history:'запись истории'};openModal('Удалить '+titles[kind]+'?',`<p class="section-intro">Запись будет удалена из студии. Экспортированные файлы и уже отправленные видеогенерации останутся доступны.</p>`,btn('Отмена','close','','ghost')+btn('Удалить','confirm-delete','trash','danger',`data-kind="${kind}" data-id="${esc(id)}"`));}
function chooseFile(accept,handler){const el=document.createElement('input');el.type='file';el.accept=accept;el.onchange=async()=>{try{if(el.files[0])await handler(el.files[0]);}catch(e){toast(e.message);}};el.click();}
async function mediaMetadata(file){const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Не удалось прочитать файл'));reader.readAsDataURL(file);});const type=file.type.split('/')[0];if(!['image','video','audio'].includes(type))throw Error('Неизвестный тип медиа');const r={data,type,mime:file.type,size:file.size,width:0,height:0,duration:0};const url=URL.createObjectURL(file);try{if(type==='image'){const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('Не удалось открыть изображение'));img.src=url;});r.width=img.naturalWidth;r.height=img.naturalHeight;}else{const el=document.createElement(type);el.preload='auto';el.muted=true;await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('Не удалось прочитать метаданные медиа')),15000);el.onloadedmetadata=()=>{clearTimeout(timer);resolve();};el.onerror=()=>{clearTimeout(timer);reject(Error('Неподдерживаемое медиа'));};el.src=url;});r.duration=Number.isFinite(el.duration)?el.duration:0;if(type==='video'){r.width=el.videoWidth;r.height=el.videoHeight;r.frame_data=[];const canvas=document.createElement('canvas');canvas.width=Math.min(1000,r.width);canvas.height=Math.round(canvas.width*r.height/r.width);for(const f of [.1,.5,.9]){await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('Не удалось извлечь кадр')),8000);el.onseeked=()=>{clearTimeout(timer);resolve();};el.currentTime=Math.max(.01,r.duration*f);});canvas.getContext('2d').drawImage(el,0,0,canvas.width,canvas.height);r.frame_data.push(canvas.toDataURL('image/jpeg',.8));}}el.removeAttribute('src');el.load();}}finally{URL.revokeObjectURL(url);}return r;}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-view]');if(nav){if(busy){toast('Дождитесь ответа AI-режиссёра');return;}saveWorkspace().catch(()=>{});view=nav.dataset.view;query='';category='';closeModal();render();return;}const ex=e.target.closest('[data-example]');if(ex){const examples={cinema:'Девушка идёт по цветущему саду. Ветер колышет лёгкое платье, камера плавно следует за ней. Тёплый вечерний свет, приглушённые розовые и оливковые оттенки. Одна непрерывная кинематографичная сцена.',product:'Кремовый флакон стоит на оливковой ткани. По поверхности скользит мягкий свет, в воздухе медленно опускается лепесток. Камера делает деликатный наезд. Тактильная предметная съёмка.',dream:'Среди травы распускается огромный пудрово-розовый цветок. Его лепестки плавно превращаются в бабочек. Камера неподвижна, утренний туман, мягкие пастельные цвета.'};S.workspace.brief=examples[ex.dataset.example];$('textarea[name=brief]').value=S.workspace.brief;autosave();return;}const target=e.target.closest('[data-action]');if(!target)return;const a=target.dataset.action,id=target.dataset.id;try{switch(a){case 'close':closeModal();break;case 'menu':$('.sidebar').classList.toggle('open');break;case 'tab-idea':tab='idea';render();break;case 'tab-result':tab='result';render();break;case 'new-idea':await saveDraft().catch(()=>{});S.workspace={id:'main',profile_id:profile().id,brief:'',reference_ids:[],parameters:defaults(profile()),result:null,messages:[]};tab='idea';await saveWorkspace();render();break;case 'direct':await direct();break;case 'save-draft':await saveDraft();break;case 'copy-prompt':await navigator.clipboard.writeText(S.workspace.result.prompt);toast('Промпт скопирован');break;case 'export-prompt':download('video-prompt.json',{...S.workspace.result,parameters:params(),references:chosen().map(({id,role,name})=>({id,role,name}))});break;case 'prepare':await prepareVideo();break;case 'generate':await generateVideo(target);break;case 'show-context':await showContext();break;case 'profile-info':showProfileEditor(profile());break;case 'add-profile':showProfileEditor();break;case 'edit-profile':showProfileEditor(S.profiles.find(x=>x.id===id));break;case 'copy-profile':{const p=structuredClone(S.profiles.find(x=>x.id===id));p._copyFrom=p.id;p.id='';p.contract='custom';p.name+=' · копия';p.status='unverified';p.verified_at='';p.request_template.model='$model';showProfileEditor(p);break;}case 'use-profile':await changeProfile(id);view='studio';render();break;case 'export-profile':{const p=S.profiles.find(x=>x.id===id);download(p.id+'.json',{format:'ai-video-studio-profile',version:1,profile:p,documents:S.documents.filter(d=>d.profiles.includes(id))});break;}case 'import-profile':chooseFile('.json',async file=>{const data=JSON.parse(await file.text()),p=data.profile||data;delete p.id;p.status='unverified';p.verified_at='';const saved=await api('profile',p);for(const d of data.documents||[]){d.id='';d.profiles=[saved.id];await api('document',d);}await reload();render();toast('Профиль импортирован. Проверьте endpoint и техническую схему.');});break;case 'check-doc-source':{target.disabled=true;try{const check=await api('check-document',{id});$('[name=content]',$('#doc-form')).value=check.content;$('#doc-diff').innerHTML='<p class="help">Источник прочитан. Это предложение обновления: локальный документ ещё не изменён.</p><pre>'+esc(check.diff)+'</pre>';docReview=true;$('#doc-submit').innerHTML=icon('check')+'Применить новую версию';toast('Изменения готовы к просмотру. Технический профиль не изменялся.');}finally{target.disabled=false;}break;}case 'add-doc':showDocEditor();break;case 'import-doc':chooseFile('.md,.txt',async file=>{if(!/\.(md|txt)$/i.test(file.name))throw Error('Нужен .md или .txt');showDocEditor(null,await file.text(),file.name.replace(/\.(md|txt)$/i,''));});break;case 'read-doc':case 'edit-doc':{const d=S.documents.find(x=>x.id===id);if(!d)throw Error('Документ удалён; использованные разделы сохранены в результате');showDocEditor(d);break;}case 'export-doc':{const d=S.documents.find(x=>x.id===id);download(d.title.replace(/[\\/:*?"<>|]/g,'_')+'.md',d.content,'text/markdown');break;}case 'preview-ref':showMediaPreview(S.references.find(x=>x.id===id));break;case 'add-ref':showRefEditor(null,target.dataset.type);break;case 'edit-ref':showRefEditor(S.references.find(x=>x.id===id));break;case 'pick-refs':showRefPicker();break;case 'apply-refs':S.workspace.reference_ids=$$('input[name=pick-reference]:checked').map(x=>x.value);await saveWorkspace();closeModal();render();break;case 'delete-doc':await remove('documents',id);break;case 'delete-profile':await remove('profiles',id);break;case 'delete-ref':await remove('references',id);break;case 'delete-history':await remove('history',id);break;case 'confirm-delete':await api('delete',{kind:target.dataset.kind,id});S=await api('state');closeModal();render();break;case 'go-settings':closeModal();view='settings';render();break;case 'go-studio':view='studio';render();break;case 'load-models':await saveSettings(false);target.disabled=true;try{const data=await api('models',{});$('#models-list').innerHTML=data.models.map(x=>option(x,x,false)).join('');toast(data.models.length+' моделей загружено. Выберите модель в поле выше.');}finally{target.disabled=false;}break;case 'clear-prompt-key':$('#settings-form').dataset.clearPrompt='yes';target.textContent='Ключ будет удалён при сохранении';break;case 'clear-video-key':target.dataset.clear='yes';target.textContent='Ключ будет удалён при сохранении';break;case 'restore-history':{const h=S.history.find(x=>x.id===id);if(!S.profiles.some(p=>p.id===h.profile_id))throw Error('Профиль удалён. Импортируйте его, чтобы продолжить.');S.workspace={id:'main',profile_id:h.profile_id,brief:h.brief||h.title,result:structuredClone(h.result),parameters:h.result.parameters||{},reference_ids:(h.reference_ids||[]).filter(id=>S.references.some(r=>r.id===id)),messages:[],story_source:h.result.story_source};await saveWorkspace();view='studio';tab='result';render();toast('История восстановлена');break;}case 'poll-job':target.disabled=true;try{await api('poll',{id});await reload();render();}finally{target.disabled=false;}break;case 'export-history':download('studio-history.json',S.history);break;}}catch(err){toast(err.message);}});
document.addEventListener('input',e=>{const el=e.target;if(el.name==='brief'){S.workspace.brief=el.value;autosave();}if(el.name==='result-prompt'){S.workspace.result.prompt=el.value;autosave();}if(el.name==='search'){const start=el.selectionStart;query=el.value;render();const next=$('[name=search]');next.focus();next.setSelectionRange(start,start);}if(el.closest('#doc-form')&&['content','source'].includes(el.name)){docReview=false;if($('#doc-submit'))$('#doc-submit').innerHTML=icon('check')+'Сохранить документ';}});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.name==='active-profile')await changeProfile(el.value);if(el.dataset.param){const k=el.dataset.param,rule=profile().schema[k];S.workspace.parameters[k]=rule.type==='boolean'?el.checked:rule.type==='integer'||rule.type==='number'?Number(el.value):el.value;if(S.workspace.result)S.workspace.result.parameters=params();autosave();}if(el.name==='category-filter'){category=el.value;render();}if(el.dataset.docEnable){const d=S.documents.find(x=>x.id===el.dataset.docEnable);d.enabled=el.checked;await api('document',d);await reload();render();}if(el.name==='doc-file'&&el.files[0]){const file=el.files[0];if(!/\.(md|txt)$/i.test(file.name))throw Error('Нужен файл .md или .txt');$('[name=content]',$('#doc-form')).value=await file.text();docReview=false;toast('Текст загружен. Изменения сохранятся после проверки.');}if(el.name==='media-file'&&el.files[0]){const file=el.files[0];if(file.size>25*1024*1024)throw Error('Для онлайн-версии используйте файл до 25 MB');$('#ref-submit').disabled=true;$('#upload-status').textContent='Читаем метаданные и ключевые кадры…';try{uploadedMedia=await mediaMetadata(file);const form=$('#ref-form');if(!form.elements.name.value)form.elements.name.value=file.name.replace(/\.[^.]+$/,'');form.elements.type.value=uploadedMedia.type;for(const k of ['width','height','duration'])form.elements[k].value=uploadedMedia[k]||'';form.elements.size_mb.value=(file.size/1024/1024).toFixed(2);form.elements.role.value=uploadedMedia.type==='video'?'Motion Reference':uploadedMedia.type==='audio'?'Audio Reference':profile().roles[0];$('#upload-status').textContent=uploadedMedia.type==='video'?'Видео прочитано · 3 ключевых кадра готовы':'Файл готов к загрузке в общую студию';}finally{$('#ref-submit').disabled=false;}}}catch(err){toast(err.message);}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,submit=e.submitter;try{if(f.id==='settings-form'){submit.disabled=true;await saveSettings();}if(f.id==='profile-form'){const v=new FormData(f),p=structuredClone(editorProfile),locked=['seedance-i2v','seedance-r2v','genjutsu-motion','genjutsu-swap','hf-seedance-i2v','hf-seedance-r2v','hf-genjutsu-motion','hf-genjutsu-swap','seedance-t2v','hf-seedance-t2v'].includes(p.id);for(const k of ['name','mode','system','user_instructions','source','verified_at'])p[k]=v.get(k);if(!locked){for(const k of ['provider','endpoint','model','poll_url'])p[k]=v.get(k);p.roles=v.get('roles').split(',').map(x=>x.trim()).filter(Boolean);p.schema=JSON.parse(v.get('schema'));p.request_template=JSON.parse(v.get('request_template'));}p.version=Number(v.get('version'));p.status=v.has('verified')?'verified':'unverified';submit.disabled=true;const copyFrom=p._copyFrom;delete p._copyFrom;const saved=await api('profile',p);if(copyFrom){for(const d of S.documents.filter(d=>d.profiles.includes(copyFrom))){await api('document',{...d,profiles:[...d.profiles,saved.id]});}}if(!p.id){const settings=structuredClone(S.settings);settings.video[saved.provider]||={name:saved.provider};await api('settings',{settings});}await reload();closeModal();render();toast('Профиль сохранён');}if(f.id==='doc-form'){const v=new FormData(f),d={...editorDoc,title:v.get('title'),category:v.get('category'),source:v.get('source'),content:v.get('content'),profiles:v.getAll('linked-profile'),enabled:v.has('enabled')};if(d.id&&d.content!==editorDoc.content&&!docReview){const result=await api('document-diff',{id:d.id,content:d.content});$('#doc-diff').innerHTML='<p class="help">Проверьте изменения перед сохранением новой версии:</p><pre>'+esc(result.diff)+'</pre>';docReview=true;$('#doc-submit').innerHTML=icon('check')+'Применить новую версию';$('#doc-diff').scrollIntoView({behavior:'smooth',block:'center'});return;}submit.disabled=true;await api('document',d);await reload();closeModal();render();toast('Документ сохранён, индекс знаний обновлён');}if(f.id==='ref-form'){const v=new FormData(f),r={...editorRef,...uploadedMedia,name:v.get('name'),type:v.get('type'),role:v.get('role'),description:v.get('description'),remote_url:v.get('remote_url'),width:Number(v.get('width')),height:Number(v.get('height')),duration:Number(v.get('duration')),fps:Number(v.get('fps')),size:uploadedMedia?.size||Number(v.get('size_mb'))*1024*1024,metadata_checked:v.has('metadata_checked')};submit.disabled=true;const saved=await api('reference',r);await reload();if(v.has('select-now')&&profile().roles.includes(saved.role))S.workspace.reference_ids=[...new Set([...S.workspace.reference_ids,saved.id])];await saveWorkspace();closeModal();render();toast('Референс сохранён: '+saved.id);}}catch(err){toast(err.message);}finally{if(submit)submit.disabled=false;}});

window.addEventListener('beforeunload',()=>{if(S&&onlineCsrf){fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json','X-Studio-Request':'local','X-CSRF-Token':onlineCsrf},body:JSON.stringify(S.workspace),keepalive:true}).catch(()=>{});}});
let connectionResults={}, connectionSequence={};
function connectionStatus(id){
  const state=connectionResults[id];
  if(!state)return '<span class="connection-idle">Не проверено</span>';
  return `<span class="connection-${esc(state.state)}">${state.state==='pending'?'<span class="spinner"></span>':''}${esc(state.message)}</span>`;
}
function connectionControls(id){return `<div class="connection-controls"><button type="button" class="btn small" data-check-connection="${esc(id)}" ${connectionResults[id]?.state==='pending'?'disabled':''}>${icon('refresh')}Проверить подключение</button><div class="connection-feedback" id="connection-status-${esc(id)}" role="status" aria-live="polite">${connectionStatus(id)}</div></div>`;}
function renderSettings(){
  const s=S.settings,p=s.prompt,standalone=typeof STANDALONE_LIVE!=='undefined';
  const providers=[...new Set(['atlas','nano',...S.profiles.map(x=>x.provider)])].filter(id=>id!=='higgsfield');
  return `${heading('Настроим вашу студию','Отдельный AI-режиссёр. Отдельный видеогенератор. Один творческий процесс.')}
  <form id="settings-form"><div class="settings-grid">
  <section class="panel"><div class="panel-head"><h2 class="panel-title">${icon('spark')}Prompt AI</h2>${badge('Текст и мультимодальность')}</div><div class="panel-body">
  <p class="help">OpenAI-совместимый API для подготовки промптов. ElysiumAI подключается так же, как модель к TavoAI: адрес, API-ключ и выбранная модель.</p>
  ${field('Base URL',input('prompt-url',p.url,'https://elysiumai.net/v1','url','data-connection-owner="prompt"'))}
  <button type="button" class="text-button" data-elysium-preset style="margin-top:9px">${icon('plus')}Подставить ElysiumAI</button>
  ${field('API-ключ',input('prompt-key','',p.has_key?'Ключ сохранён · пустое поле сохраняет текущий':'Введите API-ключ','password','autocomplete="new-password" data-connection-owner="prompt"'))}
  ${field('Модель',input('prompt-model',p.model,'Точный ID модели','text','list="models-list" data-connection-owner="prompt"'))}<datalist id="models-list"></datalist>
  <div class="inline-actions" style="margin-top:10px">${btn('Загрузить модели','load-models','refresh','small ghost')}${p.has_key?btn('Удалить ключ','clear-prompt-key','trash','small ghost danger'):''}</div>
  <label class="check-group" style="margin-top:18px"><input name="vision" type="checkbox" ${p.vision?'checked':''} data-connection-owner="prompt">Модель принимает изображения и ключевые кадры</label>
  <label class="check-group"><input name="video-input" type="checkbox" ${p.video?'checked':''} data-connection-owner="prompt">Модель принимает video_url (включать по документации API)</label>
  ${field('Температура',input('temperature',p.temperature??.6,'','number','min="0" max="2" step="0.1" data-connection-owner="prompt"'))}
  ${connectionControls('prompt')}<p class="help">Проверка отправляет короткий запрос выбранной модели. Он может тарифицироваться вашим сервисом. Видеогенерация при проверке не запускается.</p>
  </div></section>
  <section class="panel"><div class="panel-head"><h2 class="panel-title">${icon('video')}Video Providers</h2>${badge('Видеогенерация','pink')}</div><div class="panel-body">
  <p class="help">Для каждого видеосервиса используется свой ключ. Endpoint и параметры генерации находятся в профиле выбранной модели.</p>
  <div class="connection-status"><span class="dot"></span>Higgsfield API · ${s.video.higgsfield?.has_key?'ключи сохранены':'нужны Key ID и Secret'}</div>
  <div class="help-box"><strong>Отдельный API и отдельный баланс.</strong><br>Подписка и кредиты сайта Higgsfield не используются этим API.</div>
  ${field('Higgsfield · API Key ID',input('higgsfield-key-id','',s.video.higgsfield?.has_id?'ID сохранён · пустое поле сохраняет текущий':'Введите Key ID','password','autocomplete="new-password" data-connection-owner="higgsfield"'))}
  ${field('Higgsfield · API Key Secret',input('video-key-higgsfield','',s.video.higgsfield?.has_key?'Secret сохранён · пустое поле сохраняет текущий':'Введите Key Secret','password','autocomplete="new-password" data-connection-owner="higgsfield"'))}
  ${connectionControls('higgsfield')}${s.video.higgsfield?.has_key?btn('Удалить ключи Higgsfield','clear-video-key','trash','small ghost danger','data-id="higgsfield"'):''}
  ${providers.map(id=>`<div class="divider"></div><div class="connection-status"><span class="dot" style="background:${s.video[id]?.has_key?'#829252':'#c1bca5'}"></span>${esc(s.video[id]?.name||id)} · ${s.video[id]?.has_key?'ключ сохранён':'нужен API-ключ'}</div>${field(esc(id)+' · API-ключ',input('video-key-'+id,'',s.video[id]?.has_key?'Ключ сохранён · оставьте пустым, чтобы сохранить':'Введите ключ провайдера','password',`autocomplete="new-password" data-connection-owner="${esc(id)}"`))}${connectionControls(id)}${s.video[id]?.has_key?btn('Удалить ключ','clear-video-key','trash','small ghost danger',`data-id="${esc(id)}"`):''}`).join('')}
  <div class="help-box">${icon('lock')} ${standalone?'Ключи сохраняются в хранилище этого браузера и не записываются внутрь HTML-файла. При отправке файла подруге ваши ключи не передаются.':'Личные ключи шифруются на сервере и сохраняются в Supabase. Они доступны для запросов только вашему аккаунту. Пустое поле сохраняет текущий ключ.'}</div>
  <p class="help">Проверка видеопровайдера выполняется без создания платного ролика. Отправка видео требует отдельного подтверждения.</p>
  </div></section></div>
  ${standalone?`<section class="panel" style="margin-top:23px"><div class="panel-head"><h2 class="panel-title">${icon('settings')}Способ подключения HTML</h2></div><div class="panel-body"><div class="form-row">${field('Режим запросов',`<select name="transport"><option value="auto" ${s.transport==='auto'||!s.transport?'selected':''}>Автоматически: напрямую или через локальный сервер</option><option value="direct" ${s.transport==='direct'?'selected':''}>Напрямую из браузера</option><option value="bridge" ${s.transport==='bridge'?'selected':''}>Через локальный сервер</option></select>`)}${field('Адрес локального сервера',input('bridge-url',s.bridge_url||'http://127.0.0.1:8765','','url'))}</div><p class="help">ElysiumAI поддерживает прямое подключение. Higgsfield, Atlas Cloud и NanoAPI ограничивают браузерные запросы: для них автоматический режим использует локальный сервер из полной версии приложения. При недоступном сервере будет показана ошибка; платные запросы автоматически не повторяются.</p><p class="help">Хранилище привязано к браузеру и его профилю. Если браузер запрещает сохранение локальных файлов, приложение сообщит об этом и не будет показывать ложное «Сохранено».</p></div></section>`:''}
  <div class="settings-footer"><button type="submit" class="btn primary">${icon('check')}Сохранить подключения</button></div></form>`;
}
async function saveSettings(showToast=true){
  const f=$('#settings-form'),v=new FormData(f),settings=structuredClone(S.settings),keys={};
  settings.prompt={url:String(v.get('prompt-url')||'').trim(),model:String(v.get('prompt-model')||'').trim(),vision:v.has('vision'),video:v.has('video-input'),temperature:Number(v.get('temperature'))};
  if(!Number.isFinite(settings.prompt.temperature)||settings.prompt.temperature<0||settings.prompt.temperature>2)throw Error('Температура должна быть от 0 до 2');
  keys.prompt=f.dataset.clearPrompt?'__DELETE__':String(v.get('prompt-key')||'').trim();
  settings.video.higgsfield||={name:'Higgsfield API'};
  keys['higgsfield-id']=String(v.get('higgsfield-key-id')||'').trim();
  for(const [k,val] of v.entries())if(k.startsWith('video-key-')){
    const id=k.slice(10);settings.video[id]||={name:id};
    keys[id]=$(`[data-action=clear-video-key][data-id="${CSS.escape(id)}"]`)?.dataset.clear?'__DELETE__':String(val||'').trim();
  }
  if(keys.higgsfield==='__DELETE__')keys['higgsfield-id']='__DELETE__';
  if(v.has('transport')){settings.transport=v.get('transport');settings.bridge_url=String(v.get('bridge-url')||'').replace(/\/$/,'');}
  S.settings=await api('settings',{settings,keys});
  $$('input[type=password]',f).forEach(x=>{
    x.value='';const id=x.name==='prompt-key'?'prompt':x.name==='higgsfield-key-id'?'higgsfield-id':x.name.replace('video-key-','');
    const saved=id==='prompt'?S.settings.prompt.has_key:id==='higgsfield-id'?S.settings.video.higgsfield?.has_id:S.settings.video[id]?.has_key;
    x.placeholder=saved?'Ключ сохранён · пустое поле сохраняет текущий':'Введите API-ключ';
  });
  if(showToast){render();toast('Подключения и ключи сохранены');}
}
function updateConnectionStatus(id){
  const el=document.getElementById('connection-status-'+id);if(el)el.innerHTML=connectionStatus(id);
  const button=$(`[data-check-connection="${CSS.escape(id)}"]`);if(button)button.disabled=connectionResults[id]?.state==='pending';
}
async function checkConnection(id){
  const sequence=(connectionSequence[id]||0)+1;connectionSequence[id]=sequence;
  connectionResults[id]={state:'pending',message:'Идёт подключение'};updateConnectionStatus(id);
  try{
    await saveSettings(false);
    const result=await api('test-connection',{provider:id});
    if(connectionSequence[id]!==sequence)return;
    connectionResults[id]={state:'success',message:result.message||'Подключено'};
  }catch(e){if(connectionSequence[id]===sequence)connectionResults[id]={state:'error',message:e.message||'Неизвестная ошибка подключения'};}
  finally{if(connectionSequence[id]===sequence)updateConnectionStatus(id);}
}
document.addEventListener('click',e=>{
  const check=e.target.closest('[data-check-connection]');if(check){checkConnection(check.dataset.checkConnection);return;}
  if(e.target.closest('[data-elysium-preset]')){
    $('#settings-form').elements['prompt-url'].value='https://elysiumai.net/v1';delete connectionResults.prompt;connectionSequence.prompt=(connectionSequence.prompt||0)+1;updateConnectionStatus('prompt');
  }
});
document.addEventListener('input',e=>{
  const id=e.target.dataset.connectionOwner;if(!id)return;
  delete connectionResults[id];connectionSequence[id]=(connectionSequence[id]||0)+1;updateConnectionStatus(id);
});

(async()=>{try{S=await api('state');S.workspace.parameters||={};S.workspace.reference_ids||=[];savedWorkspace=queuedWorkspace=JSON.stringify(S.workspace);render();}catch(e){$('#app').innerHTML='<div class="loading">Не удалось открыть студию<span>'+esc(e.message)+'</span></div>';}})();
